const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const rasheed_point = ee.Geometry.Point(30.291, 31.472); // Mouth of Rosetta branch, Rasheed, Egypt
  const buffer_distance = 3000; // meters buffer around the point
  const roi = rasheed_point.buffer(buffer_distance);

  const date1_start = '1984-07-15';
  const date1_end = '1984-08-15';
  const date2_start = '2021-08-01';
  const date2_end = '2021-08-31';

  // 2. Data Acquisition & Preprocessing
  // Function to mask clouds for Landsat 5 (SR collection)
  function maskL5sr(image) {
    const qa = image.select('pixel_qa');
    const cloud = qa.bitwiseAnd(1 << 5)
                    .or(qa.bitwiseAnd(1 << 7))
                    .or(qa.bitwiseAnd(1 << 3)); // 3 = cloud shadow, 5 = cloud, 7 = cloud confidence
    const mask2 = image.updateMask(cloud.not());
    return mask2.divide(10000)
                .copyProperties(image, ['system:time_start']); // Scale and copy time
  }

  // Function to mask clouds for Landsat 8 (SR collection)
  function maskL8sr(image) {
    const qa = image.select('pixel_qa');
    const cloud = qa.bitwiseAnd(1 << 5)
                    .or(qa.bitwiseAnd(1 << 7))
                    .or(qa.bitwiseAnd(1 << 3)); // 3 = cloud shadow, 5 = cloud, 7 = cloud confidence
    const mask2 = image.updateMask(cloud.not());
    return mask2.divide(10000)
                .copyProperties(image, ['system:time_start']); // Scale and copy time
  }

  // Function to calculate NDWI for Landsat 5
  function calculateNDWIL5(image) {
    return image.normalizedDifference(['B2', 'B4']).rename('NDWI'); // B2: Green, B4: NIR
  }

  // Function to calculate NDWI for Landsat 8
  function calculateNDWIL8(image) {
    return image.normalizedDifference(['B3', 'B5']).rename('NDWI'); // B3: Green, B5: NIR
  }

  // Get Landsat 5 collection for 1984
  let l5_col = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterBounds(roi)
    .filterDate(date1_start, date1_end)
    .map(maskL5sr)
    .map(calculateNDWIL5);

  // Get Landsat 8 collection for 2021
  let l8_col = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
    .filterBounds(roi)
    .filterDate(date2_start, date2_end)
    .map(maskL8sr)
    .map(calculateNDWIL8);

  // Check for empty collections
  const l5_size = await l5_col.size().getInfo();
  if (l5_size === 0) {
    console.log(`No Landsat 5 images found for ${date1_start}-${date1_end}.`);
    console.log('C1');
    return;
  }

  const l8_size = await l8_col.size().getInfo();
  if (l8_size === 0) {
    console.log(`No Landsat 8 images found for ${date2_start}-${date2_end}.`);
    console.log('C1');
    return;
  }

  // Take the median image for each period
  const l5_img = l5_col.median();
  const l8_img = l8_col.median();

  // 3. Shoreline Detection and Comparison
  // Using NDWI threshold to identify water
  const water_threshold = 0; // NDWI > 0 generally indicates water

  const water1_mask = l5_img.select('NDWI').gt(water_threshold);
  const water2_mask = l8_img.select('NDWI').gt(water_threshold);

  // Calculate the total number of valid pixels in the ROI for each period
  const total_pixels1 = await l5_img.select('NDWI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30, // Landsat resolution
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const total_pixels2 = await l8_img.select('NDWI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  if (total_pixels1 === 0 || total_pixels2 === 0) {
    console.log('No valid pixels remaining after cloud masking for one or both periods.');
    console.log('C2');
    return;
  }

  // Calculate the number of water pixels
  const water_pixels1 = await water1_mask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const water_pixels2 = await water2_mask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  // Check for C3: Calculation Failure
  if (water_pixels1 === null || water_pixels2 === null || total_pixels1 === null || total_pixels2 === null) {
    console.log('Calculation resulted in null/None values.');
    console.log('C3');
    return;
  }

  // Calculate the proportion of water pixels
  const water_proportion1 = water_pixels1 / total_pixels1;
  const water_proportion2 = water_pixels2 / total_pixels2;

  // Print intermediate stats
  console.log(`1984 Images: ${l5_size} (Water Prop: ${water_proportion1.toFixed(3)}, Total Pixels: ${total_pixels1})`);
  console.log(`2021 Images: ${l8_size} (Water Prop: ${water_proportion2.toFixed(3)}, Total Pixels: ${total_pixels2})`);

  // If shoreline retreated inland, the proportion of water in the fixed ROI should increase.
  const threshold_for_change = 0.02; // A 2% increase in water proportion to signify a noticeable retreat

  if (water_proportion2 > water_proportion1 + threshold_for_change) {
    console.log('A'); // Yes, shoreline retreated
  } else {
    console.log('B'); // No, shoreline did not retreat (or advanced)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
